// GaussdbParserInit initializes any static state used to implement GaussdbParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewGaussdbParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func GaussdbParserInit() {
	staticData := &GaussdbParserParserStaticData
	staticData.once.Do(gaussdbparserParserInit)
}

// NewGaussdbParser produces a new parser instance for the optional input antlr.TokenStream.
func NewGaussdbParser(input antlr.TokenStream) *GaussdbParser {
	GaussdbParserInit()
	this := new(GaussdbParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &GaussdbParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "GaussdbParser.g4"

	return this
}

